gPe(){return"\u0695\u0627\u0648\u06ce\u0698\u06cc \u0632\u06cc\u0631\u06d5\u06a9\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f \u0632\u0627\u0646\u06cc\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06d5 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u062f\u0631\u0627\u0648\u06d5\u06a9\u06d5 (\u0646\u0627\u0648\u060c \u0695\u06d5\u06af\u06d5\u0632\u060c \u0633\u0627\u06b5\u06cc \u0644\u06d5\u062f\u0627\u06cc\u06a9\u0628\u0648\u0648\u0646\u060c \u062a\u06ce\u0628\u06cc\u0646\u06cc\u060c \u0645\u06ce\u0698\u0648\u0648\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06cc \u0648 \u062f\u06d5\u0631\u0645\u0627\u0646\u06d5\u06a9\u0627\u0646) \u0648 \u067e\u0631\u0633\u06cc\u0627\u0631\u06d5\u06a9\u06d5\u062a \u062f\u06d5\u0646\u06ce\u0631\u06ce\u062a \u0628\u06c6 OpenAI\u060c \u06a9\u06d5 \u062e\u0632\u0645\u06d5\u062a\u06af\u0648\u0632\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06cc \u0632\u06cc\u0631\u06d5\u06a9\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f\u06cc \u0644\u0627\u06cc\u06d5\u0646\u06cc \u0633\u06ce\u06cc\u06d5\u0645\u06d5\u060c \u0628\u06c6 \u0626\u0627\u0645\u0627\u062f\u06d5\u06a9\u0631\u062f\u0646\u06cc \u0648\u06d5\u06b5\u0627\u0645\u06d5\u06a9\u06d5. \u0648\u06d5\u06b5\u0627\u0645\u06d5\u06a9\u06d5 \u062a\u06d5\u0646\u0647\u0627 \u067e\u06ce\u0634\u0646\u06cc\u0627\u0631\u06ce\u06a9\u06d5 \u0628\u06c6 \u06cc\u0627\u0631\u0645\u06d5\u062a\u06cc\u062f\u0627\u0646\u062a \u0648 \u0634\u0648\u06ce\u0646\u06cc \u0695\u0627\u0648\u06ce\u0698\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06cc\u06cc \u062a\u06c6 \u0646\u0627\u06af\u0631\u06ce\u062a\u06d5\u0648\u06d5. \u0695\u0627\u0632\u06cc\u062a\u061f"},
gPd(){return"\u0695\u0627\u0632\u06cc\u0645"},
gPf(){return"\u0695\u0627\u0632\u06cc \u0646\u06cc\u0645"},
gPt(){return"\u0695\u0627\u0648\u06ce\u0698\u06cc \u0632\u06cc\u0631\u06d5\u06a9\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f"},
gP8(){return"\u062f\u06d5\u0631\u0628\u0627\u0631\u06d5\u06cc \u0626\u06d5\u0645 \u0646\u06d5\u062e\u06c6\u0634\u06d5 \u0628\u067e\u0631\u0633\u06d5"},
gPa(){return"\u067e\u06ce\u0634\u0646\u06cc\u0627\u0631\u06ce\u06a9 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5 \u06cc\u0627\u0646 \u067e\u0631\u0633\u06cc\u0627\u0631\u06cc \u062e\u06c6\u062a \u0644\u06d5 \u062e\u0648\u0627\u0631\u06d5\u0648\u06d5 \u0628\u0646\u0648\u0648\u0633\u06d5"},
gP9(){return"\u06cc\u0627\u0631\u06cc\u062f\u06d5\u062f\u06d5\u0631\u06cc \u0632\u06cc\u0631\u06d5\u06a9"},
gPr(){return"\u062f\u06d5\u0631\u0628\u0627\u0631\u06d5\u06cc \u0626\u06d5\u0645 \u0646\u06d5\u062e\u06c6\u0634\u06d5 \u0628\u067e\u0631\u0633\u06d5..."},
ga3l(){return"\u067e\u06ce\u0634\u062a\u0631 \u0628\u06c6 \u062c\u06c6\u0631\u06ce\u06a9\u06cc \u062a\u0631 \u0644\u06d5\u0645 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u062f\u0627 \u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u0627\u0648\u06d5"},
ga3n(){return"\u0647\u06d5\u0645\u0648\u0648 \u0626\u06d5\u0645 \u0686\u0627\u0631\u06d5\u06a9\u06d5 \u062f\u06cc\u0627\u0631\u06cc \u0628\u06a9\u06d5 \u06cc\u0627\u0646 \u0644\u0627\u0628\u062f\u06d5"},
gGR(){return"\u06af\u0631\u062a\u0646"},
gRH(){return"\u06af\u0631\u062a\u0646"},
gRF(){return"\u0644\u06ce\u0631\u06d5 \u0648\u06ce\u0646\u06d5\u060c \u06a4\u06cc\u062f\u06cc\u06c6\u060c \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u062f\u06d5\u0646\u06af\u060c \u06cc\u0627\u0646 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06cc\u06d5\u06a9 \u0628\u06af\u0631\u06d5 \u2014 \u067e\u0627\u0634\u0627\u0646 \u0628\u06cc\u06a9\u06d5 \u0628\u06d5 \u0647\u0627\u0648\u067e\u06ce\u0686\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06ce\u06a9 \u06cc\u0627\u0646 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u060c \u0644\u06d5 \u0647\u06d5\u0631 \u0626\u0627\u0645\u06ce\u0631\u06ce\u06a9\u06d5\u0648\u06d5."},
