gRI(){return"\u0628\u0627\u0631\u06a9\u0631\u062f\u0646"},
gRy(){return"\u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5"},
gRK(){return"\u06af\u0631\u062a\u0646\u06d5\u06a9\u0627\u0646\u062a"},
gRC(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u0646\u06d5\u06af\u06cc\u0631\u0627\u0648\u06d5."},
gwT(){return"\u06af\u0631\u062a\u0646"},
Ez(a){return"\u06af\u0631\u062a\u0646 \u0633\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0648\u0648 \u0646\u06d5\u0628\u0648\u0648: "+a},
RE(a){return"\u0646\u06d5\u062a\u0648\u0627\u0646\u0631\u0627 \u06af\u0631\u062a\u0646\u06d5\u06a9\u06d5 \u0628\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5: "+a},
gRA(){return"\u0647\u0627\u0648\u067e\u06ce\u0686\u06a9\u0631\u062f\u0646 \u0628\u06d5 \u0646\u06d5\u062e\u06c6\u0634\u2026"},
RB(a){return"\u0647\u0627\u0648\u067e\u06ce\u0686\u06a9\u0631\u0627 \u0628\u06d5 "+a},
