ga0a(){return"\u0628\u06af\u06d5\u0695\u06ce \u0628\u06d5\u062f\u0648\u0627\u06cc \u0646\u0627\u0648\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u06cc\u0627\u0646 \u0698\u0645\u0627\u0631\u06d5\u06cc \u0645\u06c6\u0628\u0627\u06cc\u0644\u2026"},
ga09(){return"\u0647\u06cc\u0686 \u0646\u06d5\u062e\u06c6\u0634\u06ce\u06a9 \u0646\u06d5\u062f\u06c6\u0632\u0631\u0627\u06cc\u06d5\u0648\u06d5."},
gPJ(){return"\u0647\u0627\u0648\u067e\u06ce\u0686\u06d5\u06a9\u0627\u0646"},
