gPH(){return"\u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5"},
gEj(){return"\u0644\u06d5 \u06af\u0631\u062a\u0646\u06d5\u06a9\u0627\u0646\u0645"},
gtP(){return"\u0628\u06cc\u0628\u06d5\u0633\u062a\u06d5\u0648\u06d5 \u0628\u06d5 \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06d5 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u062f\u0631\u0627\u0648\u06d5\u06a9\u06d5"},
gPI(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u0647\u0627\u0648\u067e\u06ce\u0686\u06ce\u06a9 \u0646\u06cc\u06cc\u06d5."},
wO(a){return"\u0647\u06d5\u06b5\u06d5\u06cc\u06d5\u06a9 \u0695\u0648\u0648\u06cc\u062f\u0627: "+a},
gEk(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u0644\u06d5 \u06af\u0631\u062a\u0646\u06d5\u06a9\u0627\u0646\u062a\u062f\u0627 \u0646\u06cc\u06cc\u06d5 \u2014 \u0633\u06d5\u0631\u06d5\u062a\u0627 \u062a\u0627\u0628\u06cc \u06af\u0631\u062a\u0646 \u0628\u06d5\u06a9\u0627\u0631\u0628\u0647\u06ce\u0646\u06d5."},
gEl(){return"\u06af\u0631\u062a\u0646\u06ce\u06a9 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5"},
gPG(){return"\u0626\u06d5\u0645 \u0641\u0627\u06cc\u0644\u06d5 \u0628\u0633\u0695\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5\u061f"},
gPF(){return"\u0626\u06d5\u0645\u06d5 \u0628\u06c6 \u0647\u06d5\u062a\u0627\u0647\u06d5\u062a\u0627\u06cc\u06d5 \u0644\u0627\u06cc \u0626\u06d5\u0645 \u0646\u06d5\u062e\u06c6\u0634\u06d5 \u062f\u06d5\u06cc\u0633\u0695\u06ce\u062a\u06d5\u0648\u06d5. \u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u067e\u0627\u0634\u06af\u06d5\u0632 \u0628\u06ce\u062a\u06d5\u0648\u06d5."},
gPL(){return"\u067e\u0632\u06cc\u0634\u06a9 \u0628\u06cc\u0646\u06cc\u0648\u06cc\u06d5\u062a\u06cc"},
gKf(){return"\u0645\u06cc\u062f\u06cc\u0627"},
gL0(){return"\u0641\u0627\u06cc\u0644\u06d5\u06a9\u0627\u0646\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u0644\u06c6\u06a9\u0627\u0644\u06cc \u0647\u06d5\u06b5\u0628\u06af\u06cc\u0631\u06ce\u062a"},
gL1(){return"\u06a9\u0627\u062a\u06ce\u06a9 \u067e\u0632\u06cc\u0634\u06a9\u06ce\u06a9 \u0647\u06d5\u0645\u0648\u0648 \u0641\u0627\u06cc\u0644\u06d5\u06a9\u0627\u0646\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06ce\u06a9\u06cc \u0628\u06cc\u0646\u06cc\u060c \u06a9\u06c6\u067e\u06cc\u06d5\u06a9\u0627\u0646\u06cc\u0627\u0646 \u0644\u06d5 \u0647\u06d5\u06b5\u06af\u0631\u062a\u0646 \u0628\u06d5 \u062e\u06c6\u06a9\u0627\u0631 \u067e\u0627\u06a9 \u062f\u06d5\u06a9\u0631\u06ce\u0646\u06d5\u0648\u06d5 \u2014 \u062a\u06c6\u0645\u0627\u0631\u06d5\u06a9\u06d5 \u062f\u06d5\u0645\u06ce\u0646\u06ce\u062a\u06d5\u0648\u06d5\u060c \u0628\u06d5\u06b5\u0627\u0645 \u0646\u0627\u0648\u06d5\u0695\u06c6\u06a9\u06d5\u06a9\u06d5 \u0646\u0627."},
gJF(){return"\u0695\u06ce\u06af\u06d5 \u0628\u06d5 \u0647\u0627\u0648\u067e\u06ce\u0686 \u0628\u062f\u06d5"},
gJG(){return"\u06a9\u0644\u06cc\u0644\u06cc \u0633\u06d5\u0631\u06d5\u06a9\u06cc \u2014 \u06a9\u0648\u0698\u0627\u0646\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0626\u06d5\u0645\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0634\u0648\u06ce\u0646\u06ce\u06a9 \u0647\u0627\u0648\u067e\u06ce\u0686\u06a9\u0631\u062f\u0646 \u062f\u06d5\u0634\u0627\u0631\u06ce\u062a\u06d5\u0648\u06d5\u060c \u0633\u06d5\u0631\u0628\u0627\u0631\u06cc \u0686\u0648\u0627\u0631 \u0695\u06ce\u06a9\u062e\u0633\u062a\u0646\u06d5\u06a9\u06d5\u06cc \u062e\u0648\u0627\u0631\u06d5\u0648\u06d5."},
gJL(){return"\u0695\u06ce\u06af\u06d5 \u0628\u06d5 \u0648\u06ce\u0646\u06d5 \u0628\u062f\u06d5"},
gJM(){return"\u0648\u06ce\u0646\u06d5\u06af\u0631\u062a\u0646 \u0648 \u0628\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u0648\u06ce\u0646\u06d5."},
gJP(){return"\u0695\u06ce\u06af\u06d5 \u0628\u06d5 \u06a4\u06cc\u062f\u06cc\u06c6 \u0628\u062f\u06d5"},
gJQ(){return"\u0628\u06d5 \u0628\u0646\u06d5\u0695\u06d5\u062a \u06a9\u0648\u0698\u0627\u0648\u06d5\u062a\u06d5\u0648\u06d5 \u2014 \u06a4\u06cc\u062f\u06cc\u06c6 \u067e\u06ce\u0634 \u0628\u0627\u0631\u06a9\u0631\u062f\u0646 \u067e\u06d5\u0633\u062a\u0627\u0648 \u0646\u0627\u06a9\u0631\u06ce\u062a\u060c \u0628\u06c6\u06cc\u06d5 \u0632\u06c6\u0631 \u0632\u06cc\u0627\u062a\u0631 \u0644\u06d5 \u0648\u06ce\u0646\u06d5 \u0634\u0648\u06ce\u0646 \u0648 \u062f\u0627\u062a\u0627 \u0628\u06d5\u06a9\u0627\u0631\u062f\u06d5\u0647\u06ce\u0646\u06ce\u062a."},
gJH(){return"\u0695\u06ce\u06af\u06d5 \u0628\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u062f\u06d5\u0646\u06af \u0628\u062f\u06d5"},
gJI(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u0646\u0627\u0645\u06d5\u06cc \u062f\u06d5\u0646\u06af\u06cc."},
gJJ(){return"\u0695\u06ce\u06af\u06d5 \u0628\u06d5 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5 \u0628\u062f\u06d5"},
gJK(){return"\u0647\u0627\u0648\u067e\u06ce\u0686\u06cc \u062c\u06c6\u0631\u06cc PDF/\u0633\u06a9\u0627\u0646 \u2014 \u0641\u06c6\u0631\u0645\u06cc \u0628\u06cc\u0645\u06d5\u060c \u0646\u0627\u0645\u06d5\u06cc \u0646\u0627\u0631\u062f\u0646 \u0648 \u0647\u062a\u062f."},
